function assert(cond, msg) { if (!cond) throw new Error('FAIL: ' + msg); }

class Inventory { constructor(){this.goods=new Map();} add(id,q){this.goods.set(id,this.count(id)+q);} remove(id,q){if(this.count(id)<q)return false;this.goods.set(id,this.count(id)-q);return true;} count(id){return this.goods.get(id)||0;} }
class Recipe { constructor(inp,out){this.inputs=inp;this.outputs=out;} }
class Crafting {
  constructor(inv,recipes){this.inv=inv;this.recipes=recipes;}
  can(id){const r=this.recipes[id];if(!r)return null;for(const i in r.inputs)if(this.inv.count(i)<r.inputs[i])return i;return true;}
  make(id){const r=this.recipes[id];if(!r||this.can(id)!==true)return false;for(const i in r.inputs)this.inv.remove(i,r.inputs[i]);for(const o in r.outputs)this.inv.add(o,r.outputs[o]);return true;}
}
const inv=new Inventory();
inv.add('wood',12);
inv.add('stone',6);
const recipes={
  planks:new Recipe({'wood':3},{'planks':4}),
  pickaxe:new Recipe({'planks':3,'stone':2},{'pickaxe':1}),
};
const craft=new Crafting(inv,recipes);

assert(craft.make('planks'), 'the first recipe succeeds');
assert(inv.count('planks')===4, 'planks were produced');
assert(inv.count('wood')===6, 'wood was NOT consumed early');
const need=craft.can('pickaxe');
assert(need===true, 'the second recipe can now proceed');
assert(craft.make('pickaxe'), 'the pickaxe is crafted');
assert(inv.count('pickaxe')===1, 'a pickaxe appears in the inventory');
console.log('gen crafting scifi/plain OK');
