class Status {
  constructor(name, duration, onExpire){this.name=name;this.duration=duration;this.onExpire=onExpire;}
  tick(){if(this.duration>0)this.duration-=1;if(this.duration===0&&this.onExpire)this.onExpire();}
}
class StatusSystem {
  constructor(){this.active=new Map();}
  add(name,dur,onExpire){const s=new Status(name,dur,onExpire);this.active.set(name,s);return s;}
  get(name){return this.active.get(name);}
  tickAll(){for(const s of this.active.values())s.tick();return this.active.size;}
}
const sys=new StatusSystem();
sys.add('poison',3,()=>console.log('poisoned'));
assert(sys.get('poison').duration===3,'duration sticks');
let sz=sys.tickAll();
assert(sz===1,'one effect remains alive');
sz=sys.tickAll();
assert(sys.get('poison').duration===1,'it ticks down');
sys.tickAll();sys.tickAll();
assert(!sys.get('poison'),'the effect expired and was cleaned up');
console.log('gen status scifi/stack OK');
