class Example extends Phaser.Scene
{
    create ()
    {
        const board = new Phaser.GameObjects.Board(this, 8, 6);

        //  8x6 grid of random colors

        const colors = [ 0xff0000, 0x00ff00, 0x0000ff, 0xffff00, 0xff00ff, 0x00ffff ];

        for (let y = 0; y < 6; y++)
        {
            for (let x = 0; x < 8; x++)
            {
                const color = Phaser.Utils.Array.GetRandom(colors);
                const tile = board.setTile(x, y, { color });
            }
        }

        this.add.existing(board);

        let selectedTile = null;

        board.on('board/tileclick', function (tile) {

            if (!selectedTile)
            {
                selectedTile = tile;
                return;
            }

            const distance = Math.abs(selectedTile.x - tile.x) + Math.abs(selectedTile.y - tile.y);

            if (distance === 1)
            {
                board.swapTiles(selectedTile, tile);
                selectedTile = null;
            }
            else
            {
                selectedTile = tile;
            }

        });

        board.on('board/swap', function (tileA, tileB) {

            const matchA = board.findMatch(tileA.x, tileA.y, tileA.tile.color);
            const matchB = board.findMatch(tileB.x, tileB.y, tileB.tile.color);

            if (matchA.length > 2 || matchB.length > 2)
            {
                board.removeTiles(matchA);
                board.removeTiles(matchB);
            }
            else
            {
                board.swapTiles(tileA, tileB);
            }

        });
    }
}

const config = {
    type: Phaser.AUTO,
    width: 800,
    height: 600,
    parent: 'phaser-example',
    scene: Example
};

const game = new Phaser.Game(config);
