class Example extends Phaser.Scene
{
    create ()
    {
        const paddle = this.add.rectangle(400, 570, 128, 16, 0x44ff88);
        const ball = this.add.circle(400, 500, 10, 0xff4444);

        const bricks = [];
        for (let c = 0; c < 9; c++)
        {
            for (let r = 0; r < 3; r++)
            {
                bricks.push(this.add.rectangle(104 + c * 80, 60 + r * 24, 76, 16, 0xffcc44));
            }
        }

        const cursors = this.input.keyboard.createCursorKeys();

        this.physics.add.existing(paddle, true);
        this.physics.add.existing(ball, true);

        ball.body.bounce.set(1);
        ball.body.setVelocity(200, -200);

        this.physics.add.collider(ball, bricks, brickHit, null, this);

        this.input.on('pointermove', pointer =>
        {

            // round position to avoid interpolation issues
            paddle.x = Math.round(pointer.x);

        });

        function brickHit (ball, brick)
        {
            brick.destroy();
        }
    }
}

const config = {
    type: Phaser.AUTO,
    parent: 'phaser-example',
    width: 800,
    height: 600,
    backgroundColor: '#efefef',
    physics: {
        default: 'arcade',
        arcade: {
            gravity: { y: 0 },
            debug: false
        }
    },
    scene: Example
};

const game = new Phaser.Game(config);
