extends SceneTree

class Inventory:
	var capacity: int
	var items: Dictionary = {}

	func _init(c: int):
		capacity = c

	func add(item: String, weight: int) -> bool:
		if weight + total_weight() > capacity:
			return false
		items[item] = weight
		return true

	func remove(item: String) -> int:
		var w := items[item]
		if w != null:
			items.erase(item)
		return w or 0

	func total_weight() -> int:
		var t: int = 0
		for _, w in items.values():
			t += w
		return t

func _init():
	var inv := Inventory.new(15)
	assert(inv.add("potion", 3), "add potion failed")
	assert(inv.add("gem", 2), "add gem failed")
	assert(not inv.add("ore", 7), "over-cap should reject ore")
	assert(inv.total_weight() == 5, "wrong total")
	inv.remove("potion")
	assert(inv.total_weight() == 2, "remove didn't lower weight")
	print("final weight: ", inv.total_weight())
	quit()
